        if (tp[1] == '.') {
            v = (tp[0] - '0') * 10 + (tp[2] - '0');
            p = tp + 4; // skip '\n'
        } else {
            v = (tp[0] - '0') * 100 + (tp[1] - '0') * 10 + (tp[2] - '0');
            p = tp + 5;
        }
