        Entry *en = &list[i];
        memcpy(o, en->name, en->len); o += en->len;
        *o++ = '=';
        fmt_tenths(&o, en->min);
        *o++ = '/';
        // mean
        int64_t q = en->sum / en->count;
        int64_t r = en->sum % en->count;
        if (r != 0) {
            int64_t ar = r < 0 ? -r : r;
            if (2 * ar >= en->count) q += (en->sum > 0 ? 1 : -1);
